import{_ as a,o,c as l,a2 as i}from"./chunks/framework.DMvgf4hZ.js";const s="/toonflow/assets/asset-library.IV-5nbX3.png",e="/toonflow/assets/director-studio.CZlIDHsa.png",r="/toonflow/assets/director-open.DSQ9Rchg.png",d="/toonflow/assets/director-model.DWc9_OxU.png",n="/toonflow/assets/director-camera.Crn5NWwZ.png",c="/toonflow/assets/director-plan.9cRXibTX.png",D=JSON.parse('{"title":"素材库与 3D 导演台","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md","lastUpdated":1794745517000}'),p={name:"guide/tools.md"};function _(b,t,m,h,k,u){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="素材库与-3d-导演台" tabindex="-1">素材库与 3D 导演台 <a class="header-anchor" href="#素材库与-3d-导演台" aria-label="Permalink to &quot;素材库与 3D 导演台&quot;">​</a></h1><h2 id="素材库" tabindex="-1">素材库 <a class="header-anchor" href="#素材库" aria-label="Permalink to &quot;素材库&quot;">​</a></h2><ol><li>右键结果节点，选择“保存到素材库”，填写完整文件名、选择位置，再点击“保存”。</li><li>点击画布左下角“素材库”，搜索刚才的名称。点击预览按钮查看内容，把文件拖回画布即可复用。</li><li>点击素材库顶部“新建文件夹”，按角色、场景或集数整理。右键素材还能重命名、移动或下载。</li><li>画布变大后，可点击左下角地图图标定位内容，或点击“整理画布”自动排布节点；需要恢复时点击弹出的“撤销整理”。</li></ol><p><img src="'+s+'" alt="素材库的搜索、预览与右键菜单"></p><h2 id="_3d-导演台" tabindex="-1">3D 导演台 <a class="header-anchor" href="#_3d-导演台" aria-label="Permalink to &quot;3D 导演台&quot;">​</a></h2><p>导演台是一个 3D 构图节点，帮助用户用摆积木的方式搭建故事空间，通过多视角截图，快速得到可被 AI 图像 / 视频模型准确理解的构图参考。</p><h3 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h3><ol><li>按 <kbd>Tab</kbd> 添加“3D 导演台”，点击节点预览打开。先点“设置 → 添加人偶”，用一个简单人物练习取景。</li><li>点击三维画面进入取景，用鼠标调整朝向，<kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> 移动，空格上升、<kbd>Shift</kbd> 下降，滚轮调焦。</li><li>点击“添加关键帧”记录取景，按 <kbd>Esc</kbd> 退出。想生成动画时，在右侧选择文本模型、输入场景和运镜要求，再点击“生成方案”。</li><li>点击关键帧的导出按钮生成图片节点，或点击“导出视频节点”保存动画。导出期间保持当前窗口可见，完成后回画布查看。</li></ol><p><img src="'+e+'" alt="3D 导演台界面：左侧 3D 空间，右侧方案与镜头区"></p><h3 id="基础使用步骤" tabindex="-1">基础使用步骤 <a class="header-anchor" href="#基础使用步骤" aria-label="Permalink to &quot;基础使用步骤&quot;">​</a></h3><ol><li><p>新建“3D 导演台”节点，点击「打开导演台」进入 3D 空间。</p><p><img src="'+r+'" alt="打开导演台后的 3D 空间与方案编辑区"></p></li><li><p>连接节点生成模型。</p><p><img src="'+d+'" alt="在 3D 空间中点击添加位置的提示"></p></li><li><p>在对话框描述模型动作和运镜要求。</p><p><img src="'+n+'" alt="选择运镜方式与角色动作"></p><p><img src="'+c+'" alt="对话框中使用参考镜头生成运镜的示例"></p></li></ol><div class="tip custom-block"><p class="custom-block-title">导出建议</p><p>导演台的导出结果是构图参考，不是最终成片。把导出的图片或视频节点接进图片生成 / 视频生成节点，再补充文字提示词，效果更可控。</p></div>',12)])])}const g=a(p,[["render",_]]);export{D as __pageData,g as default};
